import {healthGoalFields,healthHabitTemplates} from './health-config.js';
import {isHabitScheduled,healthDueReminders,healthSeries,healthTrendChart} from './health-insights.js';
const shift=(d,n)=>{const x=new Date(d+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)};
const scheduled=isHabitScheduled;
const dayKeys=['healthSun','healthMon','healthTue','healthWed','healthThu','healthFri','healthSat'];
const checked=(d,id,date)=>d.checks.some(x=>x.habitId===id&&x.date===date&&x.completed);
const sum=(records,key)=>records.reduce((a,x)=>a+x.data[key],0);
export function healthSummary(d,records,water,today,days){
  const start=shift(today,1-days),rows=records.filter(x=>x.data.recordDate>=start&&x.data.recordDate<=today);
  const checks=new Set(d.checks.filter(x=>x.completed).map(x=>`${x.habitId}:${x.date}`));let planned=0,complete=0;for(let i=0;i<days;i++){const date=shift(today,-i);for(const h of d.habits.filter(h=>scheduled(h,date))){planned++;if(checks.has(`${h.id}:${date}`))complete++}}
  const sleep=rows.filter(r=>r.kind==='sleep'),activity=rows.filter(r=>r.kind==='activity'),weights=rows.filter(r=>r.kind==='measurement').sort((a,b)=>a.data.recordDate.localeCompare(b.data.recordDate));
  return {planned,complete,sleep:sleep.length?Math.round(sum(sleep,'recordHours')/sleep.length*10)/10:null,steps:activity.length?sum(activity,'healthSteps'):null,minutes:activity.length?sum(activity,'healthMoveMinutes'):null,water:water.filter(x=>x.date>=start&&x.date<=today).reduce((n,x)=>n+x.ml,0),weightChange:weights.length>1?Math.round((weights.at(-1).data.recordWeight-weights[0].data.recordWeight)*10)/10:null};
}
export function habitStreak(d,habit,today){const dates=new Set(d.checks.filter(x=>x.habitId===habit.id&&x.completed).map(x=>x.date));let count=0;for(let i=0;i<366;i++){const date=shift(today,-i);if(date<habit.startDate)break;if(!scheduled(habit,date))continue;if(dates.has(date))count++;else if(i!==0)break;}return count}
const details=(key,title,body,open=false)=>`<details class="card stack health-disclosure" data-disclosure-key="health:${key}" ${open?'open':''}><summary><strong>${title}</strong></summary><div class="stack health-disclosure-body">${body}</div></details>`;
const action=(btn,h,t,key,op,id,extra='')=>btn(t(key),'healthAction',`data-op="${op}" data-id="${h(id)}" ${extra}`,'secondary');
const empty=t=>`<p class="empty">${t('noItems')}</p>`;
export function habitForm(habit,t,h){return `<label>${t('healthHabitName')}<input name="name" maxlength="80" required value="${h(habit?.name||'')}"></label><fieldset class="stack"><legend>${t('healthRepeat')}</legend><div class="row wrap">${dayKeys.map((k,i)=>`<label class="check-row"><input type="checkbox" name="days" value="${i}" ${(!habit||habit.days.includes(i))?'checked':''}>${h(t(k))}</label>`).join('')}</div></fieldset><label>${t('healthReminder')}<input name="reminder" type="time" value="${h(habit?.reminder||'')}"></label><small>${t('healthReminderHint')}</small>`}
export function healthGoalForm(goals,t,h){return `<p class="notice">${h(t('healthGoalHint'))}</p>${healthGoalFields.map(f=>`<label>${h(t(f.label))}${f.unit?` (${h(f.unit)})`:''}<input type="number" name="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${h(goals?.[f.key]??'')}" placeholder="${h(t('healthGoalOptional'))}"></label>`).join('')}`}
export function healthGoalPayload(fd){return Object.fromEntries(healthGoalFields.map(f=>[f.key,fd.get(f.key)===''||fd.get(f.key)==null?null:Number(fd.get(f.key))]))}
export function healthPage({state,t,h,btn,today,recordCards}){
  const d=state.wellness.health||{habits:[],checks:[],goals:{},suggestions:[],shareLinks:[],coachLinks:[],shared:[]},r=state.wellness.records;
  // Nutrition Pro is the canonical hydration source when available; never add its records twice.
  const water=state.nutrition?.water??r.filter(x=>x.kind==='water').map(x=>({date:x.data.recordDate,ml:x.data.recordMl}));
  const current=healthSummary(d,r,water,today,1),goal=state.nutrition?.goals?.waterMl;
  const localDate=ms=>{const d=new Date(ms);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
  const workouts=state.training?.sessions?.filter(s=>s.status==='finished'&&localDate(s.endedAt)===today).length??r.filter(x=>x.kind==='workout'&&x.data.recordDate===today).length;
  const recovery=r.find(x=>x.kind==='recovery'&&x.data.recordDate===today),quality=r.find(x=>x.kind==='sleepQuality'&&x.data.recordDate===today);
  const metrics=[['healthDailyHabits',`${current.complete}/${current.planned}`],['sleep',current.sleep==null?'—':`${current.sleep} h`],['healthSteps',current.steps??'—'],['water',`${current.water} ml${goal?` / ${goal} ml`:''}`],['healthTodayWorkouts',workouts],['healthEnergy',recovery?`${recovery.data.healthEnergy}/5`:'—'],['healthSleepQuality',quality?`${quality.data.healthRating}/5`:'—']];
  const meter=metrics.map(([key,value])=>`<div class="stat-box"><div class="stat green">${h(value)}</div><small>${h(t(key))}</small></div>`).join('');
  const habitRow=(x,archived=false)=>`<article class="rule stack"><div class="row space wrap"><b>${h(x.name)}</b><small>${h(t('healthStreak'))}: ${habitStreak(d,x,today)}</small></div><small>${x.days.map(i=>h(t(dayKeys[i]))).join(' · ')}${x.reminder?` · ${h(x.reminder)}`:''}</small><div class="row wrap">${archived?action(btn,h,t,'restore','healthHabitRestore',x.id):`${scheduled(x,today)?action(btn,h,t,checked(d,x.id,today)?'healthUndo':'healthComplete','healthHabitCheck',x.id,`data-completed="${!checked(d,x.id,today)}"`):''}${btn(t('wellnessEdit'),'healthForm',`data-op="healthHabitEdit" data-id="${h(x.id)}"`,'secondary')}${action(btn,h,t,'healthArchive','healthHabitArchive',x.id)}`}</div></article>`;
  const active=d.habits.filter(x=>!x.archivedDate),archived=d.habits.filter(x=>x.archivedDate);
  const habits=`${btn(t('healthAddHabit'),'healthForm','data-op="healthHabitCreate"','primary','plus')}${active.map(x=>habitRow(x)).join('')||empty(t)}${archived.length?details('archived',h(t('healthArchived')),archived.map(x=>habitRow(x,true)).join('')):''}`;
  const due=healthDueReminders(d);
  const reminders=due.length?`<section class="card stack health-reminder"><div class="row space"><h2>${h(t('healthDueReminders'))}</h2><span class="badge gold">${due.length}</span></div>${due.map(x=>`<div class="row space wrap"><div class="grow"><b>${h(x.name)}</b><small>${h(x.reminder)}</small></div>${action(btn,h,t,'healthComplete','healthHabitCheck',x.id,'data-completed="true"')}</div>`).join('')}</section>`:'';
  const goalValues={steps:current.steps,activeMinutes:current.minutes,sleepHours:current.sleep,weightKg:r.filter(x=>x.kind==='measurement'&&x.data.recordDate<=today).sort((a,b)=>b.data.recordDate.localeCompare(a.data.recordDate)||b.updatedAt-a.updatedAt)[0]?.data.recordWeight??null,habitRate:current.planned?Math.round(current.complete/current.planned*100):null};
  const goals=`<p class="muted">${h(t('healthGoalHint'))}</p>${btn(t('healthEditGoals'),'healthForm','data-op="healthGoalsSet"','primary')}${healthGoalFields.filter(f=>d.goals?.[f.key]!=null).map(f=>{const target=d.goals[f.key],actual=goalValues[f.key];return `<article class="rule stack"><div class="row space wrap"><b>${h(t(f.label))}</b><b>${actual==null?'—':h(actual)} / ${h(target)} ${h(f.unit)}</b></div>${f.key!=='weightKg'&&actual!=null?`<progress value="${Math.min(target,Math.max(0,actual))}" max="${target}"></progress>`:''}</article>`}).join('')||`<p class="empty">${h(t('healthNoGoals'))}</p>`}${goal?`<div class="rule row space wrap"><b>${h(t('water'))}</b><b>${current.water} / ${goal} ml</b>${btn(t('nutrition'),'nav','data-id="nutrition"','chip')}</div>`:''}`;
  const library=[...new Set(healthHabitTemplates.map(x=>x.group))].map(group=>details(`template:${group}`,h(t(group)),healthHabitTemplates.filter(x=>x.group===group).map(x=>`<div class="row space wrap rule"><b>${h(t(x.label))}</b>${btn(t('healthUseTemplate'),'healthForm',`data-op="healthHabitTemplate" data-id="${h(x.id)}"`,'secondary','plus')}</div>`).join(''))).join('');
  const charts=[['measurement','recordWeight','measurements','kg'],['sleep','recordHours','sleep','h'],['activity','healthSteps','healthSteps',''],['activity','healthMoveMinutes','healthMoveMinutes','min']].map(([kind,key,label,unit])=>healthTrendChart({series:healthSeries(r,kind,key,today,30),title:t(label),unit,t,h})).join('');
  const reports=[7,30].map(days=>{const s=healthSummary(d,r,water,today,days);return `<section class="rule stack"><b>${days} ${h(t('days'))}</b><div class="dashboard-metrics"><div class="stat-box"><b>${s.complete}/${s.planned}</b><small>${h(t('healthDailyHabits'))}</small>${s.planned?`<progress value="${s.complete}" max="${s.planned}"></progress>`:''}</div><div class="stat-box"><b>${s.sleep??'—'} h</b><small>${h(t('healthAverageSleep'))}</small></div><div class="stat-box"><b>${s.steps??'—'}</b><small>${h(t('healthSteps'))}</small></div><div class="stat-box"><b>${s.minutes??'—'}</b><small>${h(t('healthMoveMinutes'))}</small></div><div class="stat-box"><b>${s.water} ml</b><small>${h(t('water'))}</small></div><div class="stat-box"><b>${s.weightChange==null?'—':`${s.weightChange>0?'+':''}${s.weightChange} kg`}</b><small>${h(t('healthWeightChange'))}</small></div></div></section>`}).join('');
  const isMember=state.coaching?.role==='member';
  const coaching=`<p class="notice">${h(t('healthShareNotice'))}</p>${d.shareLinks.map(l=>`<div class="row space wrap"><b>${h(l.name)}</b>${action(btn,h,t,l.enabled?'healthRevoke':'healthAllow','healthShare',l.id,`data-enabled="${!l.enabled}"`)}</div>`).join('')}${d.coachLinks.map(l=>`<div class="row space wrap"><b>${h(l.name)}</b>${btn(t('healthSuggest'),'healthForm',`data-op="healthHabitSuggest" data-id="${h(l.id)}"`,'secondary')}</div>`).join('')}${d.suggestions.map(x=>`<div class="rule stack"><b>${h(x.name)}</b><small>${x.days.map(i=>h(t(dayKeys[i]))).join(' · ')}</small>${isMember?`<div class="row wrap">${action(btn,h,t,'accept','healthHabitRespond',x.id,'data-accept="true"')}${action(btn,h,t,'decline','healthHabitRespond',x.id,'data-accept="false"')}</div>`:''}</div>`).join('')}${d.shared.map(x=>`<article class="rule"><b>${h(x.name)}</b><p>${h(t('healthWeeklyAdherence'))}: ${x.completed}/${x.scheduled}</p></article>`).join('')}`;
  return `<div class="stack health-pro"><div class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / HEALTH PRO</span><h1>${h(t('health'))}</h1><p>${h(t('healthIntro'))}</p></div><p class="notice">${h(t('wellnessLocalNotice'))}</p>${reminders}<section class="card stack"><div class="row space wrap"><h2>${h(t('wellnessSummary'))}</h2><small>${h(today)}</small></div><div class="dashboard-metrics">${meter}</div>${btn(t('nutrition'),'nav','data-id="nutrition"','secondary')}${btn(t('trainingPro'),'nav','data-id="trainingPro"','secondary')}</section>${details('goals',h(t('healthGoals')),goals)}${details('habits',h(t('healthRecurring')),habits,true)}${details('library',h(t('healthHabitLibrary')),`<p class="muted">${h(t('healthTemplateHint'))}</p>${library}`)}${details('reports',h(t('healthReports')),reports)}${details('charts',h(t('healthCharts')),`<p class="muted">${h(t('healthChartHint'))}</p>${charts}`)}${details('coaching',h(t('healthCoaching')),coaching)}${details('records',h(t('healthRecordHistory')),recordCards)}</div>`;
}
